# frozen_string_literal: true

require 'openssl'

module Faraday
  module IntegrationHelpers
    # Throwaway certificate authority used by the SSL and proxy integration
    # specs. Everything is generated in memory, so no certificate files need to
    # be committed or generated by the CI workflow.
    class TestPKI
      Credentials = Struct.new(:cert, :key)

      attr_reader :ca_cert, :ca_key

      def initialize
        @ca_key = OpenSSL::PKey::RSA.new(2048)
        @ca_cert = build_certificate('Faraday Test CA', ca_key, ca_key, nil) do |cert, factory|
          [
            factory.create_extension('basicConstraints', 'CA:TRUE', true),
            factory.create_extension('keyUsage', 'keyCertSign,cRLSign', true),
            factory.create_extension('subjectKeyIdentifier', 'hash', false)
          ].each { |ext| cert.add_extension(ext) }
        end
      end

      # Issues a certificate signed by this CA.
      #
      # @param common_name [String] certificate subject CN
      # @param dns_names [Array<String>] DNS subjectAltNames
      # @param ip_addresses [Array<String>] IP subjectAltNames
      # @return [Credentials]
      def issue(common_name, dns_names: [], ip_addresses: [])
        key = OpenSSL::PKey::RSA.new(2048)
        sans = dns_names.map { |name| "DNS:#{name}" } + ip_addresses.map { |ip| "IP:#{ip}" }

        cert = build_certificate(common_name, key, ca_key, ca_cert) do |built, factory|
          built.add_extension(factory.create_extension('basicConstraints', 'CA:FALSE', true))
          built.add_extension(factory.create_extension('subjectAltName', sans.join(','), false)) if sans.any?
        end

        Credentials.new(cert, key)
      end

      # Writes the CA certificate to disk, as expected by the `ca_file` option.
      def write_ca_file(path)
        File.write(path, ca_cert.to_pem)
        path
      end

      # @return [OpenSSL::X509::Store] a store that only trusts this CA
      def cert_store
        OpenSSL::X509::Store.new.tap { |store| store.add_cert(ca_cert) }
      end

      private

      def build_certificate(common_name, key, signing_key, issuer_cert)
        cert = OpenSSL::X509::Certificate.new
        cert.version = 2
        cert.serial = rand(1..(2**32))
        cert.subject = OpenSSL::X509::Name.parse("/CN=#{common_name}")
        cert.issuer = issuer_cert ? issuer_cert.subject : cert.subject
        cert.public_key = key.public_key
        cert.not_before = Time.now - 60
        cert.not_after = Time.now + 3600

        factory = OpenSSL::X509::ExtensionFactory.new
        factory.subject_certificate = cert
        factory.issuer_certificate = issuer_cert || cert
        yield cert, factory

        cert.sign(signing_key, OpenSSL::Digest.new('SHA256'))
        cert
      end
    end
  end
end
